// Build industry-specific Apify search queries based on b2b_vertical
const data = $input.first().json;
const vertical = data.b2b_vertical;
const location = data.location || 'United States';
const industry = data.industry || '';
const sub = JSON.parse(data.insurance_sub_targets || '[]');
const extraKeywords = JSON.parse(data.keywords || '[]');

const VERTICAL_QUERIES = {
  marketing_agency: [
    'marketing agency',
    'digital marketing agency',
    'social media marketing agency',
    'advertising agency',
    'content marketing agency',
    'SEO agency',
    'PPC agency'
  ],
  saas_software: [
    'SaaS company',
    'software company',
    'tech startup',
    'software development company',
    'cloud software',
    'B2B software'
  ],
  business_consultant: [
    'business consultant',
    'management consultant',
    'business coach',
    'strategy consultant',
    'growth consultant'
  ],
  commercial_support: [
    'commercial cleaning',
    'janitorial services',
    'facility management',
    'commercial landscaping',
    'office maintenance'
  ],
  recruiting_firm: [
    'staffing agency',
    'recruiting firm',
    'executive search firm',
    'talent acquisition',
    'headhunter agency'
  ],
  insurance_agency: [
    'insurance agency',
    'insurance broker',
    'commercial insurance',
    'business insurance'
  ]
};

let queries = VERTICAL_QUERIES[vertical] || [industry || 'business'];

// For insurance agencies, optionally target their B2B clients instead
if (vertical === 'insurance_agency' && sub.length > 0) {
  queries = [];
  if (sub.includes('construction')) {
    queries.push('general contractor', 'construction company', 'roofing contractor', 'electrical contractor', 'plumbing company');
  }
  if (sub.includes('medical')) {
    queries.push('medical office', 'dental office', 'healthcare clinic', 'physical therapy clinic', 'chiropractic office');
  }
  if (sub.includes('manufacturing')) {
    queries.push('manufacturing company', 'industrial manufacturer', 'metal fabrication', 'plastics manufacturer', 'food manufacturer');
  }
}

// Mix in custom keywords if provided
if (extraKeywords.length > 0) {
  queries = [...new Set([...queries, ...extraKeywords])];
}

// Limit to 8 search terms max for Apify
queries = queries.slice(0, 8);

return [{
  json: {
    ...data,
    apify_queries: queries,
    apify_location: location,
    search_label: `${vertical} in ${location}`
  }
}];

// Normalize Apify Google Places results into consistent business objects
const items = $input.all();
const inputs = $('Store Inputs').first().json;

const businesses = [];

for (const item of items) {
  const place = item.json;

  // Skip if no name or not a real business
  if (!place.title && !place.name) continue;

  const name = place.title || place.name || 'Unknown Business';
  const website = place.website || place.url || null;
  const email = place.emailAddress || place.email || null;
  const phone = place.phoneNumber || place.phone || null;
  const address = place.address || place.location?.address || null;
  const rating = place.totalScore || place.rating || null;
  const reviews = place.reviewsCount || place.reviewCount || place.userRatingsTotal || 0;
  const category = (place.categories && place.categories[0]) || place.primaryType || inputs.b2b_vertical || null;

  businesses.push({
    name,
    website,
    email,
    phone,
    address,
    rating: rating ? parseFloat(rating) : null,
    reviews: parseInt(reviews) || 0,
    category,
    industry: inputs.industry || inputs.b2b_vertical,
    service: inputs.client_service || inputs.industry || inputs.b2b_vertical,
    location: inputs.location,
    raw_data: JSON.stringify(place).substring(0, 500)
  });
}

if (businesses.length === 0) {
  // Return a placeholder so workflow doesn't die empty
  return [{ json: { __empty: true, reason: 'No businesses found in Apify response' } }];
}

return businesses.map(b => ({ json: b }));

